import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
import { dirname, join } from 'path';

const STATE_FILENAME = 'state.json';

export interface PluginState {
  active_guild_id?: string;
  active_guild_name?: string;
  bot_user_id?: string;
  bot_username?: string;
  last_verified_at?: string;
}

export function getStatePath(): string {
  const dataDir = process.env.CLAUDE_PLUGIN_DATA;
  if (!dataDir) {
    return join(process.cwd(), '.discord-state.json');
  }
  return join(dataDir, STATE_FILENAME);
}

export function loadState(): PluginState {
  const p = getStatePath();
  if (!existsSync(p)) return {};
  try {
    return JSON.parse(readFileSync(p, 'utf8')) as PluginState;
  } catch {
    return {};
  }
}

export function saveState(next: PluginState): PluginState {
  const p = getStatePath();
  const dir = dirname(p);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  writeFileSync(p, JSON.stringify(next, null, 2));
  return next;
}

export function patchState(patch: Partial<PluginState>): PluginState {
  const current = loadState();
  return saveState({ ...current, ...patch });
}

export class NoActiveGuildError extends Error {
  constructor() {
    super(
      'No active Discord guild is set. The user should run `/discord:setup` to pick the guild this bot will manage.',
    );
    this.name = 'NoActiveGuildError';
  }
}

export function getActiveGuildId(): string {
  const id = loadState().active_guild_id;
  if (!id) throw new NoActiveGuildError();
  return id;
}

import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { Routes } from 'discord-api-types/v10';
import type { APIUser } from 'discord-api-types/v10';
import { formatDiscordError, getRest } from '../client.js';
import { patchState } from '../state.js';
import { tokenGuard } from '../guards.js';

const READ_ONLY = {
  readOnlyHint: true,
  destructiveHint: false,
  openWorldHint: true,
} as const;

export function registerWhoamiTool(server: McpServer): void {
  server.registerTool(
    'discord_whoami',
    {
      description:
        "Verifies the configured Discord bot token by fetching the bot's identity (GET /users/@me). Returns the bot's username, id, discriminator, and feature flags. Use this first when troubleshooting — it confirms the token works.",
      inputSchema: {},
      annotations: READ_ONLY,
    },
    async () => {
      const guard = tokenGuard();
      if (guard) return guard;
      try {
        const rest = getRest();
        const user = (await rest.get(Routes.user('@me'))) as APIUser;
        patchState({
          bot_user_id: user.id,
          bot_username: user.username,
          last_verified_at: new Date().toISOString(),
        });
        return {
          content: [
            {
              type: 'text' as const,
              text: JSON.stringify(
                {
                  ok: true,
                  bot: {
                    id: user.id,
                    username: user.username,
                    global_name: user.global_name,
                    discriminator: user.discriminator,
                    bot: user.bot,
                    verified: user.verified,
                    flags: user.flags,
                  },
                },
                null,
                2,
              ),
            },
          ],
        };
      } catch (err) {
        return {
          isError: true,
          content: [
            {
              type: 'text' as const,
              text: formatDiscordError(err),
            },
          ],
        };
      }
    },
  );

}

import { z } from 'zod';
import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { GuildOnboardingMode, GuildOnboardingPromptType, Routes } from 'discord-api-types/v10';
import type { APIGuildOnboarding } from 'discord-api-types/v10';
import { formatDiscordError, getRest } from '../client.js';
import { getActiveGuildId } from '../state.js';
import { activeGuildGuard } from '../guards.js';

const READ_ONLY = {
  readOnlyHint: true,
  destructiveHint: false,
  openWorldHint: true,
} as const;

const MUTATING = {
  readOnlyHint: false,
  destructiveHint: false,
  openWorldHint: true,
} as const;

const PROMPT_TYPE_TO_NUM: Record<string, GuildOnboardingPromptType> = {
  multiple_choice: GuildOnboardingPromptType.MultipleChoice,
  dropdown: GuildOnboardingPromptType.Dropdown,
};

const PROMPT_NUM_TO_NAME: Record<number, string> = {
  [GuildOnboardingPromptType.MultipleChoice]: 'multiple_choice',
  [GuildOnboardingPromptType.Dropdown]: 'dropdown',
};

const MODE_TO_NUM: Record<string, GuildOnboardingMode> = {
  default: GuildOnboardingMode.OnboardingDefault,
  advanced: GuildOnboardingMode.OnboardingAdvanced,
};

const MODE_NUM_TO_NAME: Record<number, string> = {
  [GuildOnboardingMode.OnboardingDefault]: 'default',
  [GuildOnboardingMode.OnboardingAdvanced]: 'advanced',
};

function formatOnboarding(o: APIGuildOnboarding): Record<string, unknown> {
  return {
    guild_id: o.guild_id,
    enabled: o.enabled,
    mode: MODE_NUM_TO_NAME[o.mode] ?? `unknown(${o.mode})`,
    default_channel_ids: o.default_channel_ids,
    prompts: o.prompts.map((p) => ({
      id: p.id,
      type: PROMPT_NUM_TO_NAME[p.type] ?? `unknown(${p.type})`,
      title: p.title,
      single_select: p.single_select,
      required: p.required,
      in_onboarding: p.in_onboarding,
      options: p.options.map((opt) => ({
        id: opt.id,
        title: opt.title,
        description: opt.description ?? null,
        channel_ids: opt.channel_ids,
        role_ids: opt.role_ids,
        emoji: opt.emoji ?? null,
      })),
    })),
  };
}

const emojiSchema = z.object({
  id: z.string().nullable().optional().describe('Custom emoji ID, null for unicode.'),
  name: z.string().optional().describe('Unicode char or custom emoji name.'),
  animated: z.boolean().optional(),
});

const promptOptionSchema = z.object({
  title: z.string().min(1).max(50).describe('Option label (max 50 chars).'),
  description: z.string().max(100).optional().describe('Optional helper text (max 100 chars).'),
  channel_ids: z.array(z.string()).optional().describe('Channels granted when this option is picked.'),
  role_ids: z.array(z.string()).optional().describe('Roles granted when this option is picked.'),
  emoji: emojiSchema.optional().describe('Icon shown next to the option.'),
});

const promptSchema = z.object({
  type: z
    .enum(['multiple_choice', 'dropdown'])
    .describe("UI: 'multiple_choice'=cards/grid, 'dropdown'=collapsible select."),
  title: z.string().min(1).max(100).describe('Question shown to the new member.'),
  options: z.array(promptOptionSchema).min(1).max(50).describe('Pickable options (1-50).'),
  single_select: z.boolean().optional().describe('When true, only one option may be picked. Default: true.'),
  required: z
    .boolean()
    .optional()
    .describe('Member must answer to finish onboarding. Default: true.'),
  in_onboarding: z
    .boolean()
    .optional()
    .describe('Show during initial onboarding flow (vs only in Channels & Roles browser). Default: true.'),
});

export function registerOnboardingTools(server: McpServer): void {
  server.registerTool(
    'discord_get_onboarding',
    {
      description:
        "Returns the active guild's onboarding config (GET /guilds/{id}/onboarding). Includes enabled flag, mode (default=only default channels count, advanced=prompt-granted channels count too), default_channel_ids granted on join, and the prompt list with options (each option grants its own channel_ids and role_ids).",
      inputSchema: {},
      annotations: READ_ONLY,
    },
    async () => {
      const guard = activeGuildGuard();
      if (guard) return guard;
      try {
        const rest = getRest();
        const onboarding = (await rest.get(
          Routes.guildOnboarding(getActiveGuildId()),
        )) as APIGuildOnboarding;
        return {
          content: [
            { type: 'text' as const, text: JSON.stringify(formatOnboarding(onboarding), null, 2) },
          ],
        };
      } catch (err) {
        return {
          isError: true,
          content: [{ type: 'text' as const, text: formatDiscordError(err) }],
        };
      }
    },
  );

  server.registerTool(
    'discord_modify_onboarding',
    {
      description:
        "Replaces the active guild's onboarding config (PUT /guilds/{id}/onboarding). Requires Community to be enabled. Pass only fields you want to set; omitted fields keep their current value (unlike pure PUT, the SDK merges with current state). Discord requires at least 7 default channels OR enough prompt-granted channels to satisfy onboarding constraints — set mode='advanced' if you want prompt channels to count.",
      inputSchema: {
        prompts: z
          .array(promptSchema)
          .max(5)
          .optional()
          .describe(
            'Up to 5 onboarding prompts (questions). REPLACES the existing prompts list. Each prompt has 1-50 options.',
          ),
        default_channel_ids: z
          .array(z.string())
          .optional()
          .describe(
            'Channel IDs every new member gets opted into. REPLACES the existing list. In default mode, must satisfy Discord onboarding minimums (~7 channels including a community-relevant mix).',
          ),
        enabled: z.boolean().optional().describe('Toggle onboarding on/off.'),
        mode: z
          .enum(['default', 'advanced'])
          .optional()
          .describe(
            "'default'=only default_channel_ids count toward Discord's minimum, 'advanced'=channels granted by prompt options also count.",
          ),
        reason: z.string().max(512).optional(),
      },
      annotations: MUTATING,
    },
    async ({ prompts, default_channel_ids, enabled, mode, reason }) => {
      const guard = activeGuildGuard();
      if (guard) return guard;
      try {
        const rest = getRest();
        const body: Record<string, unknown> = {};
        if (prompts !== undefined) {
          body.prompts = prompts.map((p, pIdx) => ({
            id: pIdx.toString(),
            type: PROMPT_TYPE_TO_NUM[p.type],
            title: p.title,
            single_select: p.single_select ?? true,
            required: p.required ?? true,
            in_onboarding: p.in_onboarding ?? true,
            options: p.options.map((opt, oIdx) => ({
              id: `${pIdx}-${oIdx}`,
              title: opt.title,
              description: opt.description ?? null,
              channel_ids: opt.channel_ids ?? [],
              role_ids: opt.role_ids ?? [],
              emoji: opt.emoji ?? null,
            })),
          }));
        }
        if (default_channel_ids !== undefined) body.default_channel_ids = default_channel_ids;
        if (enabled !== undefined) body.enabled = enabled;
        if (mode !== undefined) body.mode = MODE_TO_NUM[mode];
        const onboarding = (await rest.put(Routes.guildOnboarding(getActiveGuildId()), {
          body,
          reason,
        })) as APIGuildOnboarding;
        return {
          content: [
            {
              type: 'text' as const,
              text: JSON.stringify({ ok: true, onboarding: formatOnboarding(onboarding) }, null, 2),
            },
          ],
        };
      } catch (err) {
        return {
          isError: true,
          content: [{ type: 'text' as const, text: formatDiscordError(err) }],
        };
      }
    },
  );
}

import { z } from 'zod';
import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { Routes } from 'discord-api-types/v10';
import type { APIGuild, APIPartialGuild, APIUser } from 'discord-api-types/v10';
import { formatDiscordError, getRest } from '../client.js';
import { loadState, patchState } from '../state.js';
import { tokenGuard } from '../guards.js';

const READ_ONLY = {
  readOnlyHint: true,
  destructiveHint: false,
  openWorldHint: true,
} as const;

const STATE_WRITE = {
  readOnlyHint: false,
  destructiveHint: false,
  openWorldHint: false,
} as const;

interface PartialGuildWithOwner extends APIPartialGuild {
  owner?: boolean;
  permissions?: string;
}

export function registerGuildSetupTools(server: McpServer): void {
  server.registerTool(
    'discord_list_guilds',
    {
      description:
        "Lists all Discord guilds (servers) the bot is currently a member of (GET /users/@me/guilds). Use this during setup so the user can pick which guild this bot will manage. Returns id, name, owner flag, and permissions string for each guild. If the result is empty, call discord_get_invite_url to give the user a link for adding the bot.",
      inputSchema: {},
      annotations: READ_ONLY,
    },
    async () => {
      const guard = tokenGuard();
      if (guard) return guard;
      try {
        const rest = getRest();
        const raw = (await rest.get(Routes.userGuilds())) as PartialGuildWithOwner[];
        return {
          content: [
            {
              type: 'text' as const,
              text: JSON.stringify(
                {
                  count: raw.length,
                  guilds: raw.map((g) => ({
                    id: g.id,
                    name: g.name,
                    icon: g.icon ?? null,
                    owner: g.owner ?? false,
                    permissions: g.permissions ?? null,
                    features: g.features,
                  })),
                },
                null,
                2,
              ),
            },
          ],
        };
      } catch (err) {
        return {
          isError: true,
          content: [{ type: 'text' as const, text: formatDiscordError(err) }],
        };
      }
    },
  );

  server.registerTool(
    'discord_set_active_guild',
    {
      description:
        "Saves the active Discord guild for this plugin so all subsequent admin tools (channels, roles, etc.) operate on it. Verifies access by calling GET /guilds/{id} — if the bot is not in the guild or lacks permission, returns the Discord error. On success, persists guild_id and guild_name to ${CLAUDE_PLUGIN_DATA}/state.json.",
      inputSchema: {
        guild_id: z
          .string()
          .min(1)
          .describe('The Discord guild (server) ID to make active. Get this from discord_list_guilds.'),
      },
      annotations: STATE_WRITE,
    },
    async ({ guild_id }) => {
      const guard = tokenGuard();
      if (guard) return guard;
      try {
        const rest = getRest();
        const guild = (await rest.get(Routes.guild(guild_id))) as APIGuild;
        const next = patchState({
          active_guild_id: guild.id,
          active_guild_name: guild.name,
          last_verified_at: new Date().toISOString(),
        });
        return {
          content: [
            {
              type: 'text' as const,
              text: JSON.stringify(
                {
                  ok: true,
                  active_guild: {
                    id: next.active_guild_id,
                    name: next.active_guild_name,
                  },
                },
                null,
                2,
              ),
            },
          ],
        };
      } catch (err) {
        return {
          isError: true,
          content: [{ type: 'text' as const, text: formatDiscordError(err) }],
        };
      }
    },
  );

  server.registerTool(
    'discord_get_active_guild',
    {
      description:
        'Returns the currently-active Discord guild from plugin state plus the cached bot identity. Read-only — does not call the Discord API. Fields are null if setup has not been run yet.',
      inputSchema: {},
      annotations: READ_ONLY,
    },
    async () => {
      const state = loadState();
      return {
        content: [
          {
            type: 'text' as const,
            text: JSON.stringify(
              {
                active_guild_id: state.active_guild_id ?? null,
                active_guild_name: state.active_guild_name ?? null,
                bot_user_id: state.bot_user_id ?? null,
                bot_username: state.bot_username ?? null,
                last_verified_at: state.last_verified_at ?? null,
              },
              null,
              2,
            ),
          },
        ],
      };
    },
  );

  server.registerTool(
    'discord_get_invite_url',
    {
      description:
        "Generates the OAuth2 URL the user opens to add this bot to a guild they own or admin. Defaults to Administrator permissions (integer 8) — what this plugin needs for full functionality. Includes integration_type=0 (GUILD_INSTALL) to ensure the bot installs to a server, not a user account. Use when discord_list_guilds returns 0 guilds, or when the user wants to add the bot to another guild.",
      inputSchema: {
        permissions: z
          .string()
          .optional()
          .describe(
            'Discord permissions integer as a string. Default "8" = Administrator. Use "8" unless the user explicitly asks for narrower permissions.',
          ),
      },
      annotations: READ_ONLY,
    },
    async ({ permissions }) => {
      const guard = tokenGuard();
      if (guard) return guard;
      try {
        const rest = getRest();
        const user = (await rest.get(Routes.user('@me'))) as APIUser;
        const perms = permissions ?? '8';
        const params = new URLSearchParams({
          client_id: user.id,
          scope: 'bot applications.commands',
          permissions: perms,
          integration_type: '0',
        });
        const url = `https://discord.com/oauth2/authorize?${params.toString()}`;
        return {
          content: [
            {
              type: 'text' as const,
              text: JSON.stringify(
                {
                  invite_url: url,
                  bot_id: user.id,
                  bot_username: user.username,
                  permissions: perms,
                  integration_type: 'GUILD_INSTALL',
                  note:
                    perms === '8'
                      ? 'Administrator (full access). Required for AutoMod, role management, and most admin operations.'
                      : 'Custom permissions integer.',
                  troubleshooting:
                    "If the OAuth2 page only asks for 'Create slash commands' (no server picker, no Administrator checkbox), the bot's app isn't configured for Guild Install. Fix: https://discord.com/developers/applications → your app → Installation → set Installation Contexts to include 'Guild Install', then under Default Install Settings → Guild Install set scopes to bot + applications.commands and permissions to Administrator. Save, then reopen the invite URL.",
                },
                null,
                2,
              ),
            },
          ],
        };
      } catch (err) {
        return {
          isError: true,
          content: [{ type: 'text' as const, text: formatDiscordError(err) }],
        };
      }
    },
  );
}

import { z } from 'zod';
import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { formatDiscordError, getRest } from '../client.js';
import { tokenGuard } from '../guards.js';

const ESCAPE_HATCH = {
  readOnlyHint: false,
  destructiveHint: true,
  openWorldHint: true,
} as const;

export function registerRawTool(server: McpServer): void {
  server.registerTool(
    'discord_raw_request',
    {
      description:
        "Escape hatch for any Discord REST endpoint not covered by a dedicated tool (e.g., guild widget, integrations, voice regions, sticker packs, application commands). The bot token is sent automatically. Path must start with '/' and reference the API path AFTER the version (e.g., '/guilds/{id}/widget', NOT '/v10/guilds/...'). For mutations, prefer dedicated tools where they exist — this skips the friendly schema layer.",
      inputSchema: {
        method: z
          .enum(['GET', 'POST', 'PUT', 'PATCH', 'DELETE'])
          .describe('HTTP method.'),
        path: z
          .string()
          .min(1)
          .describe(
            "Endpoint path starting with '/'. Example: '/guilds/123/widget' or '/users/@me/connections'. Do NOT include the API version prefix.",
          ),
        body: z
          .record(z.string(), z.any())
          .optional()
          .describe('JSON body for POST/PUT/PATCH/DELETE. Pass an object; it will be serialized.'),
        query: z
          .record(z.string(), z.union([z.string(), z.number(), z.boolean()]))
          .optional()
          .describe('Query string params as a flat object. Values are coerced to strings.'),
        reason: z
          .string()
          .max(512)
          .optional()
          .describe('X-Audit-Log-Reason header for mutating endpoints.'),
      },
      annotations: ESCAPE_HATCH,
    },
    async ({ method, path, body, query, reason }) => {
      const guard = tokenGuard();
      if (guard) return guard;
      if (!path.startsWith('/')) {
        return {
          isError: true,
          content: [
            {
              type: 'text' as const,
              text: `path must start with '/'. Got: ${path}`,
            },
          ],
        };
      }
      try {
        const rest = getRest();
        const route = path as `/${string}`;
        const opts: Record<string, unknown> = {};
        if (body !== undefined) opts.body = body;
        if (reason !== undefined) opts.reason = reason;
        if (query) {
          const params: Record<string, string> = {};
          for (const [k, v] of Object.entries(query)) params[k] = String(v);
          opts.query = new URLSearchParams(params);
        }
        let result: unknown;
        switch (method) {
          case 'GET':
            result = await rest.get(route, opts);
            break;
          case 'POST':
            result = await rest.post(route, opts);
            break;
          case 'PUT':
            result = await rest.put(route, opts);
            break;
          case 'PATCH':
            result = await rest.patch(route, opts);
            break;
          case 'DELETE':
            result = await rest.delete(route, opts);
            break;
        }
        return {
          content: [
            {
              type: 'text' as const,
              text: JSON.stringify(
                { ok: true, method, path, result: result ?? null },
                null,
                2,
              ),
            },
          ],
        };
      } catch (err) {
        return {
          isError: true,
          content: [{ type: 'text' as const, text: formatDiscordError(err) }],
        };
      }
    },
  );
}

import { z } from 'zod';
import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { Routes } from 'discord-api-types/v10';
import type { APIGuildWelcomeScreen } from 'discord-api-types/v10';
